// Mapeia a linha do Google Form/Sheets para o payload de /viabilidade,
// aplica defaults de mercado e lista campos obrigatórios faltantes.
const row = $json;
const num = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(String(v).replace(/\./g, '').replace(',', '.').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const pct = (v, d) => { const n = num(v); if (n === null) return d; return n > 1 ? n / 100 : n; };
const def = (v, d) => (v === null ? d : v);

const setor = String(row['Setor'] ?? '').trim();
const quadra = String(row['Quadra'] ?? '').trim();
const empreendimento = String(row['Empreendimento'] ?? '').trim();
const area = num(row['Área do lote (m²)']);
const nLotes = num(row['Nº de lotes']);
const gleba = num(row['Custo da gleba (R$)']);
const infra = num(row['Custo de infra (R$)']);
const mesesObra = num(row['Meses de obra']);
const mesesVenda = num(row['Meses de venda']);
let taxa = num(row['Taxa-alvo anual (%)']);
if (taxa !== null && taxa > 1) taxa = taxa / 100;
const email = String(row['Email'] ?? '').trim();

const obrig = {
  'Setor': setor, 'Quadra': quadra, 'Área do lote': area, 'Nº de lotes': nLotes,
  'Custo da gleba': gleba, 'Custo de infra': infra, 'Meses de obra': mesesObra,
  'Meses de venda': mesesVenda, 'Taxa-alvo anual': taxa, 'Email': email || null,
};
const missing = Object.entries(obrig)
  .filter(([, v]) => v === null || v === '')
  .map(([k]) => k);

const custos = {
  comissao_pct: pct(row['Comissão (%)'], 0.06),
  impostos_pct: pct(row['Impostos (%)'], 0.04),
  marketing_pct: pct(row['Marketing (%)'], 0.03),
  admin_mensal: def(num(row['Admin mensal (R$)']), 0),
  licenciamento: def(num(row['Licenciamento (R$)']), 0),
};
const nParcelas = def(num(row['Parcelas']), 12);
const mesInicio = def(num(row['Início das vendas (mês)']), 6);
const testada = def(num(row['Testada (m)']), area ? Math.max(5, Math.round(Math.sqrt(area))) : 10);

const payload = {
  terreno: { setor, quadra, area_lote_m2: area, testada },
  projeto: {
    n_lotes: nLotes ? Math.round(nLotes) : null,
    custo_gleba: gleba,
    custo_infra: infra ? { minimo: infra * 0.8, moda: infra, maximo: infra * 1.4 } : null,
    meses_obra: mesesObra ? Math.round(mesesObra) : null,
    meses_vendas: mesesVenda
      ? { minimo: Math.max(1, Math.round(mesesVenda * 0.5)), moda: Math.round(mesesVenda), maximo: Math.round(mesesVenda * 2) }
      : null,
    n_parcelas: Math.round(nParcelas),
    taxa_alvo_anual: taxa,
    custos,
    mes_inicio_vendas: Math.round(mesInicio),
  },
  n_sims: 5000,
  incluir_distribuicao: false,
};

return { setor, quadra, empreendimento, email, taxa_alvo_anual: taxa, missing, payload };

// Veredito + link do relatório (Streamlit) + colunas legíveis para planilha/email.
const STREAMLIT_BASE = 'http://localhost:8501'; // troque pela URL pública ao publicar
const r = $json;
const m = $('Montar payload').item.json;
const pl = m.payload;
const prob = Math.round((r.prob_viavel ?? 0) * 100);
const faixa = r.faixa_preco_m2 || {};
const sens = (r.sensibilidade && r.sensibilidade[0]) ? r.sensibilidade[0].variavel : '—';
const nomes = {
  preco_lote: 'preço de venda do lote',
  custo_infra: 'custo de infraestrutura',
  meses_vendas: 'velocidade de absorção',
};
const sensTxt = nomes[sens] || sens;
const taxaPct = Math.round((m.taxa_alvo_anual || 0) * 100);
const brl = (v) => 'R$ ' + Math.round(v).toLocaleString('pt-BR');
const tir = (r.tir_anual && r.tir_anual.p50 != null) ? Math.round(r.tir_anual.p50 * 100) + '%' : '—';
const empreendimento = m.empreendimento || '';
const local = empreendimento
  ? `${empreendimento} — setor ${m.setor} / quadra ${m.quadra}`
  : `Terreno setor ${m.setor} / quadra ${m.quadra}`;
const veredito =
  `${local}: ${prob}% de chance de superar a meta de ${taxaPct}% a.a. ` +
  `Resultado mais sensível a ${sensTxt}. ` +
  `Faixa de preço estimada: ${brl(faixa.inf)}–${brl(faixa.sup)}/m² (mediana ${brl(faixa.med)}).`;

// link do relatório interativo (query string montada à mão — o sandbox do n8n
// não tem URLSearchParams; encodeURIComponent existe em qualquer JS)
const t = pl.terreno, pr = pl.projeto, c = pr.custos;
const campos = {
  empreendimento, setor: t.setor, quadra: t.quadra, area_lote_m2: t.area_lote_m2, testada: t.testada,
  n_lotes: pr.n_lotes, custo_gleba: pr.custo_gleba,
  infra_min: pr.custo_infra.minimo, infra_moda: pr.custo_infra.moda, infra_max: pr.custo_infra.maximo,
  meses_obra: pr.meses_obra,
  vendas_min: pr.meses_vendas.minimo, vendas_moda: pr.meses_vendas.moda, vendas_max: pr.meses_vendas.maximo,
  n_parcelas: pr.n_parcelas, taxa_alvo_anual: pr.taxa_alvo_anual, mes_inicio_vendas: pr.mes_inicio_vendas,
  comissao_pct: c.comissao_pct, impostos_pct: c.impostos_pct, marketing_pct: c.marketing_pct,
  admin_mensal: c.admin_mensal, licenciamento: c.licenciamento, rho_mercado: 0.5,
};
const q = Object.keys(campos).map((k) => k + '=' + encodeURIComponent(campos[k])).join('&');
const link_relatorio = STREAMLIT_BASE + '/?' + q;

return {
  data_hora: new Date().toLocaleString('pt-BR'),
  empreendimento, setor: m.setor, quadra: m.quadra, email: m.email,
  prob_viavel: prob + '%', preco_mediano_m2: brl(faixa.med),
  preco_faixa_m2: `${brl(faixa.inf)} – ${brl(faixa.sup)}`,
  tir_mediana: tir, mais_sensivel: sensTxt, veredito, link_relatorio,
};

